-- V35: conjugation paradigms for the presence-indicativus lesson.
-- Present-tense example sentences (person x number = 9 per verb) for the verb
-- lesson presence-indicativus. Source: etcetera/grammar/sanskrit_verbs_present.json.
-- Served by ConjugationParadigmService as an index-based carousel (one verb per page).

CREATE TABLE curriculum.conjugation_forms (
    id                  UUID PRIMARY KEY,
    topic_code          VARCHAR(80)  NOT NULL,
    lemma_iast          VARCHAR(120) NOT NULL,
    lemma_devanagari    VARCHAR(120),
    meaning_ru          VARCHAR(200),
    voice               VARCHAR(40)  NOT NULL,
    person              INT          NOT NULL CHECK (person IN (1, 2, 3)),
    number_type         VARCHAR(40)  NOT NULL,
    sentence_iast       VARCHAR(300) NOT NULL,
    sentence_devanagari VARCHAR(300) NOT NULL,
    translation_ru      VARCHAR(300) NOT NULL,
    CONSTRAINT uq_conjugation_forms UNIQUE (topic_code, lemma_iast, voice, person, number_type)
);

COMMENT ON TABLE curriculum.conjugation_forms IS
    'Present-tense conjugation paradigm cells (example sentences, person x number) for verb lessons.';

